import { useState, useEffect } from 'react';
import { GoogleLogin, googleLogout } from '@react-oauth/google';
import { jwtDecode } from 'jwt-decode';
import { UserPlus, Users, Trash2, Award, Activity, Home, DollarSign, CreditCard, BarChart2, PlusCircle, PieChart, TrendingDown, TrendingUp, Edit2, AlertCircle, Search, Settings, Calendar } from 'lucide-react';

interface Player {
  id: string;
  name: string;
  jerseyNumber: string;
  position: string;
  battingHand: string;
  createdAt: string;
}

interface Payment {
  id: string;
  playerId: string;
  playerName: string;
  amount: number;
  description: string;
  notes?: string;
  date: string;
}

interface Expense {
  id: string;
  category: string;
  amount: number;
  description: string;
  date: string;
}

interface Game {
  id: string;
  opponent: string;
  date: string;
  time: string;
  location: string;
  result: string;
}

const API_URL = 'http://localhost:5000/api/players';
const PAYMENT_API_URL = 'http://localhost:5000/api/payments';
const EXPENSE_API_URL = 'http://localhost:5000/api/expenses';
const GAME_API_URL = 'http://localhost:5000/api/games';

function App() {
  const [user, setUser] = useState<any>(null); // Auth State
  const [activeTab, setActiveTab] = useState('Inicio');

  const [players, setPlayers] = useState<Player[]>([]);
  const [loadingPlayers, setLoadingPlayers] = useState(true);

  const [payments, setPayments] = useState<Payment[]>([]);
  const [loadingPayments, setLoadingPayments] = useState(true);

  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loadingExpenses, setLoadingExpenses] = useState(true);

  const [games, setGames] = useState<Game[]>([]);
  const [loadingGames, setLoadingGames] = useState(true);

  const [formData, setFormData] = useState({
    name: '',
    jerseyNumber: '',
    position: 'Infield',
    battingHand: 'Right',
  });

  const [paymentFormData, setPaymentFormData] = useState({
    playerId: '',
    amount: '',
    description: 'Pago de Play',
    otherDescription: '',
    notes: ''
  });

  const [expenseFormData, setExpenseFormData] = useState({
    category: 'Arbitraje',
    amount: '',
    description: '',
    date: new Date().toISOString().split('T')[0]
  });

  const [gameFormData, setGameFormData] = useState({
    opponent: '',
    date: new Date().toISOString().split('T')[0],
    time: '',
    location: '',
    result: 'Pendiente'
  });

  // App Configuration State
  const [config, setConfig] = useState({
    teamName: 'Equipo',
    primaryColor: '#38bdf8'
  });
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Edit & Delete Modal States
  const [deleteModal, setDeleteModal] = useState<{ isOpen: boolean, type: string, id: string }>({ isOpen: false, type: '', id: '' });
  const [editModal, setEditModal] = useState<{ isOpen: boolean, type: string, data: any }>({ isOpen: false, type: '', data: null });

  // Search & Date Filters
  const [playerSearch, setPlayerSearch] = useState('');
  const [paymentSearchConcept, setPaymentSearchConcept] = useState('Todos');
  const [paymentSearchGameId, setPaymentSearchGameId] = useState('');
  const [paymentSearch, setPaymentSearch] = useState('');
  const [expenseSearch, setExpenseSearch] = useState('');
  const [gameSearch, setGameSearch] = useState('');

  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const positions = ['Pitcher', 'Catcher', 'First Base', 'Infield', 'Outfield', 'Designated Hitter'];
  const expenseCategories = ['Arbitraje', 'Bolas', 'Juego', 'Bebidas/Comida', 'Equipo', 'Otro'];

  // Auth Effect
  useEffect(() => {
    const storedUser = localStorage.getItem('softball_user');
    if (storedUser) setUser(JSON.parse(storedUser));

    const savedConfig = localStorage.getItem('softball_config');
    if (savedConfig) setConfig(JSON.parse(savedConfig));
  }, []);

  useEffect(() => {
    if (user) {
      fetchPlayers();
      fetchPayments();
      fetchExpenses();
      fetchGames();
    }
  }, [user]);

  const handleLoginSuccess = (credentialResponse: any) => {
    const decoded = jwtDecode(credentialResponse.credential);
    setUser(decoded);
    localStorage.setItem('softball_user', JSON.stringify(decoded));
  };

  const logout = () => {
    googleLogout();
    setUser(null);
    setPlayers([]);
    setPayments([]);
    setExpenses([]);
    setGames([]);
    localStorage.removeItem('softball_user');
  };

  const saveConfig = (newConfig: any) => {
    setConfig(newConfig);
    localStorage.setItem('softball_config', JSON.stringify(newConfig));
    setIsSettingsOpen(false);
  };

  // Auth Header Generator
  const getAuthHeaders = () => {
    return {
      'Content-Type': 'application/json',
      'x-user-id': user?.sub || ''
    };
  };

  // GET Fetchers
  const fetchPlayers = async () => {
    try {
      setLoadingPlayers(true);
      const res = await fetch(API_URL, { headers: getAuthHeaders() });
      if (res.ok) {
        const data = await res.json();
        setPlayers(data);
      }
    } catch (err) {
      console.error('Failed to fetch players:', err);
    } finally {
      setLoadingPlayers(false);
    }
  };

  const fetchPayments = async () => {
    try {
      setLoadingPayments(true);
      const res = await fetch(PAYMENT_API_URL, { headers: getAuthHeaders() });
      if (res.ok) {
        const data = await res.json();
        setPayments(data);
      }
    } catch (err) {
      console.error('Failed to fetch payments:', err);
    } finally {
      setLoadingPayments(false);
    }
  };

  const fetchExpenses = async () => {
    try {
      setLoadingExpenses(true);
      const res = await fetch(EXPENSE_API_URL, { headers: getAuthHeaders() });
      if (res.ok) {
        const data = await res.json();
        setExpenses(data);
      }
    } catch (err) {
      console.error('Failed to fetch expenses:', err);
    } finally {
      setLoadingExpenses(false);
    }
  };

  const fetchGames = async () => {
    try {
      setLoadingGames(true);
      const res = await fetch(GAME_API_URL, { headers: getAuthHeaders() });
      if (res.ok) {
        const data = await res.json();
        setGames(data);
      }
    } catch (err) {
      console.error('Failed to fetch games:', err);
    } finally {
      setLoadingGames(false);
    }
  };

  // POST Handlers
  const handlePlayerSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.jerseyNumber) return;

    try {
      const res = await fetch(API_URL, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify(formData),
      });

      if (res.ok) {
        const newPlayer = await res.json();
        setPlayers([newPlayer, ...players]);
        setFormData({ name: '', jerseyNumber: '', position: 'Infield', battingHand: 'Right' });
      }
    } catch (err) {
      console.error('Failed to create player:', err);
    }
  };

  const handlePaymentSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!paymentFormData.playerId || !paymentFormData.amount) return;

    const selectedPlayer = players.find(p => p.id === paymentFormData.playerId);
    if (!selectedPlayer) return;

    try {
      const res = await fetch(PAYMENT_API_URL, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify({
          playerId: selectedPlayer.id,
          playerName: selectedPlayer.name,
          amount: Number(paymentFormData.amount),
          description: paymentFormData.description === 'Otro' ? paymentFormData.otherDescription : paymentFormData.description,
          notes: paymentFormData.notes
        }),
      });

      if (res.ok) {
        const newPayment = await res.json();
        setPayments([newPayment, ...payments]);
        setPaymentFormData({ ...paymentFormData, amount: '', notes: '', otherDescription: '' });
      }
    } catch (err) {
      console.error('Failed to create payment:', err);
    }
  };

  const handleExpenseSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!expenseFormData.amount || !expenseFormData.description) return;

    try {
      const res = await fetch(EXPENSE_API_URL, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify({
          category: expenseFormData.category,
          amount: Number(expenseFormData.amount),
          description: expenseFormData.description,
          date: expenseFormData.date ? new Date(expenseFormData.date + 'T12:00:00') : new Date()
        }),
      });

      if (res.ok) {
        const newExpense = await res.json();
        setExpenses([newExpense, ...expenses]);
        setExpenseFormData({ ...expenseFormData, amount: '', description: '', date: new Date().toISOString().split('T')[0] });
      }
    } catch (err) {
      console.error('Failed to create expense:', err);
    }
  };

  const handleGameSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!gameFormData.opponent || !gameFormData.date) return;

    try {
      const res = await fetch(GAME_API_URL, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify(gameFormData),
      });

      if (res.ok) {
        const newGame = await res.json();
        const updatedGames = [newGame, ...games].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
        setGames(updatedGames);
        setGameFormData({ opponent: '', date: new Date().toISOString().split('T')[0], time: '', location: '', result: 'Pendiente' });
      }
    } catch (err) {
      console.error('Failed to create game:', err);
    }
  };

  const openEditModal = (type: string, data: any) => {
    setEditModal({ isOpen: true, type, data: { ...data } });
  };

  const handleEditSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const url = editModal.type === 'player' ? `${API_URL}/${editModal.data.id}` :
      editModal.type === 'payment' ? `${PAYMENT_API_URL}/${editModal.data.id}` :
        editModal.type === 'expense' ? `${EXPENSE_API_URL}/${editModal.data.id}` :
          `${GAME_API_URL}/${editModal.data.id}`;

    try {
      const payload = { ...editModal.data };
      if (editModal.type === 'payment') payload.amount = Number(payload.amount);
      if (editModal.type === 'expense') payload.amount = Number(payload.amount);

      const res = await fetch(url, {
        method: 'PUT',
        headers: getAuthHeaders(),
        body: JSON.stringify(payload)
      });

      if (res.ok) {
        const updatedItem = await res.json();

        if (editModal.type === 'player') setPlayers(players.map(p => p.id === updatedItem.id ? updatedItem : p));
        else if (editModal.type === 'payment') setPayments(payments.map(p => p.id === updatedItem.id ? updatedItem : p));
        else if (editModal.type === 'expense') setExpenses(expenses.map(ex => ex.id === updatedItem.id ? updatedItem : ex));
        else if (editModal.type === 'game') setGames(games.map(g => g.id === updatedItem.id ? updatedItem : g).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime()));

        setEditModal({ isOpen: false, type: '', data: null });
      }
    } catch (err) {
      console.error('Failed to update:', err);
    }
  }

  const confirmDelete = (type: string, id: string) => {
    setDeleteModal({ isOpen: true, type, id });
  };

  const executeDelete = async () => {
    const { type, id } = deleteModal;
    const url = type === 'player' ? `${API_URL}/${id}` :
      type === 'payment' ? `${PAYMENT_API_URL}/${id}` :
        type === 'expense' ? `${EXPENSE_API_URL}/${id}` :
          `${GAME_API_URL}/${id}`;

    try {
      const res = await fetch(url, { method: 'DELETE', headers: getAuthHeaders() });
      if (res.ok) {
        if (type === 'player') setPlayers(players.filter(p => p.id !== id));
        else if (type === 'payment') setPayments(payments.filter(p => p.id !== id));
        else if (type === 'expense') setExpenses(expenses.filter(e => e.id !== id));
        else if (type === 'game') setGames(games.filter(g => g.id !== id));
      }
    } catch (err) {
      console.error('Failed to delete:', err);
    } finally {
      setDeleteModal({ isOpen: false, type: '', id: '' });
    }
  };

  const isDateInRange = (dateString: string) => {
    if (!startDate && !endDate) return true;

    const itemDate = new Date(dateString);
    itemDate.setHours(0, 0, 0, 0);

    let isAfterStart = true;
    let isBeforeEnd = true;

    if (startDate) {
      const s = new Date(startDate + 'T00:00:00');
      isAfterStart = itemDate >= s;
    }

    if (endDate) {
      const e = new Date(endDate + 'T00:00:00');
      // For endDate, we include the entire day
      e.setHours(23, 59, 59, 999);
      isBeforeEnd = itemDate <= e;
    }

    return isAfterStart && isBeforeEnd;
  };

  // Filter Variables
  const filteredPlayers = players.filter(p =>
    p.name.toLowerCase().includes(playerSearch.toLowerCase()) ||
    p.jerseyNumber.includes(playerSearch) ||
    p.position.toLowerCase().includes(playerSearch.toLowerCase())
  );

  const filteredPayments = payments.filter(p => {
    const conceptMatch = paymentSearchConcept === 'Todos' || p.description === paymentSearchConcept;
    const matchSearch = p.playerName.toLowerCase().includes(paymentSearch.toLowerCase()) ||
      p.description.toLowerCase().includes(paymentSearch.toLowerCase()) ||
      (p.notes && p.notes.toLowerCase().includes(paymentSearch.toLowerCase()));
    return conceptMatch && matchSearch && isDateInRange(p.date);
  });

  const filteredExpenses = expenses.filter(e => {
    const matchSearch = e.category.toLowerCase().includes(expenseSearch.toLowerCase()) ||
      e.description.toLowerCase().includes(expenseSearch.toLowerCase());
    return matchSearch && isDateInRange(e.date);
  });

  const filteredGames = games.filter(g => {
    const matchSearch = g.opponent.toLowerCase().includes(gameSearch.toLowerCase()) ||
      g.location.toLowerCase().includes(gameSearch.toLowerCase());
    return matchSearch && isDateInRange(g.date);
  });

  const handleQuickPayment = async (player: Player, gameDateStr: string, gameOpponent: string) => {
    const amountStr = window.prompt(`Monto a cobrar a ${player.name} para el juego Vs ${gameOpponent}:`, "10");
    if (!amountStr) return;
    const amount = Number(amountStr);
    if (isNaN(amount) || amount <= 0) {
      alert("Monto inválido.");
      return;
    }

    try {
      const payload = {
        playerId: player.id,
        playerName: player.name,
        amount: amount,
        description: 'Pago de Play',
        notes: `Juego Vs ${gameOpponent} (${gameDateStr})`
      };
      const res = await fetch(PAYMENT_API_URL, {
        method: 'POST',
        headers: getAuthHeaders(),
        body: JSON.stringify(payload),
      });

      if (res.ok) {
        const newPayment = await res.json();
        setPayments([newPayment, ...payments]);
      } else {
        alert("Ocurrió un error al guardar el pago rápido.");
      }
    } catch (err) {
      console.error('Failed to create quick payment:', err);
      alert("Error de red al guardar el pago.");
    }
  };

  // Derived Dashboard Stats (Global / Historical)
  const totalIncome = payments.reduce((acc, curr) => acc + curr.amount, 0);
  const totalExpenses = expenses.reduce((acc, curr) => acc + curr.amount, 0);
  const balance = totalIncome - totalExpenses;

  // Login View
  if (!user) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', padding: '2rem', textAlign: 'center' }}>
        <div style={{ marginBottom: '2.5rem', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
          <img src="/logo.png" alt="ZeratyX" style={{ height: '80px', objectFit: 'contain', marginBottom: '1rem' }} />
          <p className="header-subtitle">Gestión Segura de {config.teamName}</p>
        </div>

        <div className="glass-panel" style={{ padding: '3rem 2rem', display: 'flex', flexDirection: 'column', alignItems: 'center', width: '100%', maxWidth: '400px' }}>
          <Activity size={48} color={config.primaryColor} style={{ marginBottom: '1.5rem' }} />
          <h2 style={{ fontSize: '1.25rem', color: '#f8fafc', marginBottom: '0.5rem' }}>Bienvenido de nuevo</h2>
          <p style={{ color: '#94a3b8', fontSize: '0.9rem', marginBottom: '2rem' }}>Por favor inicia sesión con tu cuenta de Google para continuar.</p>

          <GoogleLogin
            onSuccess={handleLoginSuccess}
            onError={() => {
              console.log('Login Failed');
            }}
            useOneTap
          />
        </div>
      </div>
    );
  }

  const renderModals = () => {
    return (
      <>
        {isSettingsOpen && (
          <div className="modal-overlay">
            <div className="modal-content">
              <div className="modal-header">
                <h3 className="modal-title">
                  <Settings size={24} color={config.primaryColor} /> Configuración de la App
                </h3>
              </div>
              <div className="modal-body">
                <div className="form-group">
                  <label className="form-label">Nombre del Equipo</label>
                  <input className="input-field" value={config.teamName} onChange={(e) => setConfig({ ...config, teamName: e.target.value })} />
                </div>
                <div className="form-group">
                  <label className="form-label">Color Principal</label>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                    <input type="color" className="input-field" value={config.primaryColor} onChange={(e) => setConfig({ ...config, primaryColor: e.target.value })} style={{ height: '50px', padding: '0.2rem', cursor: 'pointer', maxWidth: '80px' }} />
                    <span style={{ color: config.primaryColor, fontWeight: 'bold' }}>{config.primaryColor}</span>
                  </div>
                </div>
              </div>
              <div className="modal-footer">
                <button className="btn-secondary" onClick={() => setIsSettingsOpen(false)}>Cancelar</button>
                <button className="btn-primary" onClick={() => saveConfig(config)} style={{ background: config.primaryColor, width: 'auto' }}>Guardar Cambios</button>
              </div>
            </div>
          </div>
        )}

        {deleteModal.isOpen && (
          <div className="modal-overlay">
            <div className="modal-content">
              <div className="modal-header border-b-0">
                <h3 className="modal-title" style={{ color: '#ef4444' }}>
                  <AlertCircle size={24} /> Confirmar Eliminación
                </h3>
              </div>
              <div className="modal-body">
                <p>¿Estás seguro de que deseas eliminar este registro? Esta acción es irreversible y afectará el balance e historial del equipo.</p>
              </div>
              <div className="modal-footer">
                <button className="btn-secondary" onClick={() => setDeleteModal({ isOpen: false, type: '', id: '' })}>Cancelar</button>
                <button className="btn-danger" onClick={executeDelete}>
                  <Trash2 size={18} style={{ marginRight: '4px' }} /> Sí, Eliminar
                </button>
              </div>
            </div>
          </div>
        )}

        {editModal.isOpen && (
          <div className="modal-overlay">
            <div className="modal-content">
              <div className="modal-header">
                <h3 className="modal-title">
                  <Edit2 size={24} color={config.primaryColor} /> Editar Registro
                </h3>
              </div>
              <div className="modal-body">
                <form id="editForm" onSubmit={handleEditSubmit}>
                  {editModal.type === 'player' && (
                    <>
                      <div className="form-group"><label className="form-label">Nombre</label><input className="input-field" value={editModal.data.name} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, name: e.target.value } })} required /></div>
                      <div className="form-group"><label className="form-label">Número de Camiseta</label><input className="input-field" type="number" value={editModal.data.jerseyNumber} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, jerseyNumber: e.target.value } })} required /></div>
                      <div className="form-group"><label className="form-label">Posición</label>
                        <select className="input-field" value={editModal.data.position} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, position: e.target.value } })}>{positions.map(pos => <option key={pos} value={pos}>{pos}</option>)}</select>
                      </div>
                    </>
                  )}
                  {editModal.type === 'payment' && (
                    <>
                      <div className="form-group"><label className="form-label">Monto ($)</label><input className="input-field" type="number" step="0.01" value={editModal.data.amount} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, amount: e.target.value } })} required /></div>
                      <div className="form-group"><label className="form-label">Concepto</label>
                        <input className="input-field" value={editModal.data.description} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, description: e.target.value } })} required />
                      </div>
                      <div className="form-group"><label className="form-label">Descripción</label><input className="input-field" value={editModal.data.notes || ''} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, notes: e.target.value } })} /></div>
                    </>
                  )}
                  {editModal.type === 'expense' && (
                    <>
                      <div className="form-group"><label className="form-label">Categoría</label>
                        <select className="input-field" value={editModal.data.category} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, category: e.target.value } })}>{expenseCategories.map(cat => <option key={cat} value={cat}>{cat}</option>)}</select>
                      </div>
                      <div className="form-group"><label className="form-label">Monto ($)</label><input className="input-field" type="number" step="0.01" value={editModal.data.amount} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, amount: e.target.value } })} required /></div>
                      <div className="form-group"><label className="form-label">Fecha del Gasto</label><input className="input-field" type="date" value={editModal.data.date ? new Date(editModal.data.date).toISOString().split('T')[0] : ''} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, date: e.target.value } })} required style={{ colorScheme: 'dark' }} /></div>
                      <div className="form-group"><label className="form-label">Descripción</label><input className="input-field" value={editModal.data.description} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, description: e.target.value } })} required /></div>
                    </>
                  )}
                  {editModal.type === 'game' && (
                    <>
                      <div className="form-group"><label className="form-label">Oponente / Vs</label><input className="input-field" value={editModal.data.opponent} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, opponent: e.target.value } })} required /></div>
                      <div className="form-group"><label className="form-label">Fecha</label><input className="input-field" type="date" value={editModal.data.date ? new Date(editModal.data.date).toISOString().split('T')[0] : ''} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, date: e.target.value } })} required style={{ colorScheme: 'dark' }} /></div>
                      <div className="form-group"><label className="form-label">Hora (Opcional)</label><input className="input-field" type="time" value={editModal.data.time || ''} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, time: e.target.value } })} style={{ colorScheme: 'dark' }} /></div>
                      <div className="form-group"><label className="form-label">Lugar / Estadio (Opcional)</label><input className="input-field" value={editModal.data.location || ''} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, location: e.target.value } })} /></div>
                      <div className="form-group"><label className="form-label">Resultado</label>
                        <select className="input-field" value={editModal.data.result} onChange={(e) => setEditModal({ ...editModal, data: { ...editModal.data, result: e.target.value } })}>
                          <option value="Pendiente">Pendiente</option><option value="Victoria">Victoria</option><option value="Derrota">Derrota</option><option value="Empate">Empate</option><option value="Suspendido">Suspendido</option>
                        </select>
                      </div>
                    </>
                  )}
                </form>
              </div>
              <div className="modal-footer">
                <button className="btn-secondary" onClick={() => setEditModal({ isOpen: false, type: '', data: null })}>Cancelar</button>
