                <div className="form-group"><label className="form-label">Monto ($)</label><input type="number" min="1" step="0.01" className="input-field" placeholder="0.00" value={paymentFormData.amount} onChange={e => setPaymentFormData({ ...paymentFormData, amount: e.target.value })} required /></div>
