                const gameDateStr = new Date(selectedGame.date).toLocaleDateString();
                const expectedNotesFragment1 = `Vs ${selectedGame.opponent}`;
                const expectedNotesFragment2 = gameDateStr;

                // Evaluar la lista de jugadores que han pagado
                const payers = players.map(p => {
                  const hasPaid = payments.find(pay => 
                    pay.playerId === p.id && 
                    pay.description === 'Pago de Play' && 
                    pay.notes && 
                    pay.notes.includes(expectedNotesFragment1)
                  );
                  return { player: p, payment: hasPaid };
                });

                const countPaid = payers.filter(p => p.payment).length;
                const countUnpaid = payers.length - countPaid;

                return (
                  <div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1rem', padding: '1rem', background: 'rgba(255,255,255,0.05)', borderRadius: '12px' }}>
