                      <div style={{ textAlign: 'center', flex: 1 }}>
                        <span style={{ color: '#ef4444', fontSize: '1.5rem', fontWeight: 'bold' }}>{countUnpaid}</span>
                        <div style={{ color: '#94a3b8', fontSize: '0.85rem' }}>Faltan</div>
