          <p className="header-subtitle" style={{ fontSize: '0.85rem' }}>Hola, <span style={{ color: '#f8fafc' }}>{user.given_name || user.name}</span></p>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <button className="btn-icon" onClick={() => setIsSettingsOpen(true)} title="Configuración de la App">
            <Settings size={22} color="#f8fafc" />
          </button>
          <button className="btn-secondary" onClick={logout} style={{ padding: '0.5rem 1rem', fontSize: '0.8rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            Salir
          </button>
        </div>
      </header>

      <main>{renderContent()}</main>

      {renderModals()}

      <nav className="bottom-nav">
        {navItems.map((item) => {
          const Icon = item.icon;
          const isActive = activeTab === item.id;
          return <button key={item.id} className={`nav-item ${isActive ? 'active' : ''}`} onClick={() => setActiveTab(item.id)}><Icon size={24} className="nav-icon" color={isActive ? config.primaryColor : '#94a3b8'} /><span className="nav-label" style={{ color: isActive ? config.primaryColor : '#94a3b8' }}>{item.title}</span></button>;
        })}
      </nav>
    </div>
  );
}

export default App;
